#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<long long> num11(20);
vector<long long> pow10(20);
int answer = -1;

void initialize()
{
    pow10[0] = 1;
    for (int i = 1; i <= 17; ++i)
        pow10[i] = pow10[i - 1] * 10;

    num11[0] = 0;
    for (int i = 1; i <= 17; ++i)
        num11[i] = num11[i - 1] * 10 + 1;
}

int length_of(long long x)
{
    int length = 0;
    do
    {
        ++length;
        x /= 10;
    } while (x != 0);
    return length;
}

void search(int pos, long long x, int cnt)
{
    if (answer != -1 && cnt >= answer)
        return;
    if (x == 0 || pos == 0)
    {
        if (answer == -1 || cnt < answer)
            answer = cnt;
        return;
    }
    if (x < 0)
        x = -x;

    long long temp_x = x;
    int temp_cnt = 0;
    while (temp_x >= pow10[pos - 1])
    {
        temp_x -= num11[pos];
        temp_cnt += pos;
    }
    search(pos - 1, temp_x, cnt + temp_cnt);

    temp_x = num11[pos + 1] - x;
    temp_cnt = 0;
    while (temp_x >= pow10[pos - 1])
    {
        temp_x -= num11[pos];
        temp_cnt += pos;
    }
    search(pos - 1, temp_x, cnt + pos + 1 + temp_cnt);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    initialize();

    long long x;
    cin >> x;
    answer = -1;
    search(length_of(x), x, 0);
    cout << answer << "\n";

    return 0;
}
